class Solution {
    private int[] parent;
    private int[] rank;

    public int[] findRedundantConnection(int[][] edges) {
        int n = edges.length;
        parent = new int[n + 1];
        rank = new int[n + 1];
        for (int node = 1; node <= n; node++) {
            parent[node] = node;
        }

        for (int[] edge : edges) {
            if (!union(edge[0], edge[1])) {
                return edge;
            }
        }
        return new int[]{};
    }

    private int find(int node) {
        if (parent[node] != node) {
            parent[node] = find(parent[node]);
        }
        return parent[node];
    }

    private boolean union(int a, int b) {
        int rootA = find(a);
        int rootB = find(b);
        if (rootA == rootB) {
            return false;
        }
        if (rank[rootA] < rank[rootB]) {
            int temp = rootA;
            rootA = rootB;
            rootB = temp;
        }
        parent[rootB] = rootA;
        if (rank[rootA] == rank[rootB]) {
            rank[rootA]++;
        }
        return true;
    }
}

import java.util.*;

class Solution {
    public int[] findRedundantConnection(int[][] edges) {
        int n = edges.length;
        List<List<Integer>> graph = new ArrayList<>();
        for (int node = 0; node <= n; node++) {
            graph.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            boolean[] seen = new boolean[n + 1];
            if (hasPath(edge[0], edge[1], graph, seen)) {
                return edge;
            }
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }
        return new int[]{};
    }

    private boolean hasPath(int source, int target, List<List<Integer>> graph, boolean[] seen) {
        if (source == target) {
            return true;
        }
        seen[source] = true;
        for (int next : graph.get(source)) {
            if (!seen[next] && hasPath(next, target, graph, seen)) {
                return true;
            }
        }
        return false;
    }
}

import java.util.*;

class Solution {
    public int[] findRedundantConnection(int[][] edges) {
        int n = edges.length;
        List<List<Integer>> graph = new ArrayList<>();
        int[] degree = new int[n + 1];
        for (int node = 0; node <= n; node++) {
            graph.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
            degree[edge[0]]++;
            degree[edge[1]]++;
        }

        boolean[] inCycleCore = new boolean[n + 1];
        Arrays.fill(inCycleCore, true);
        Queue<Integer> leaves = new ArrayDeque<>();
        for (int node = 1; node <= n; node++) {
            if (degree[node] == 1) {
                leaves.offer(node);
            }
        }

        while (!leaves.isEmpty()) {
            int node = leaves.poll();
            inCycleCore[node] = false;
            for (int next : graph.get(node)) {
                degree[next]--;
                if (degree[next] == 1) {
                    leaves.offer(next);
                }
            }
        }

        for (int i = edges.length - 1; i >= 0; i--) {
            int[] edge = edges[i];
            if (inCycleCore[edge[0]] && inCycleCore[edge[1]]) {
                return edge;
            }
        }
        return new int[]{};
    }
}

import java.util.*;

class Solution {
    public int[] findRedundantConnection(int[][] edges) {
        int n = edges.length;
        for (int remove = edges.length - 1; remove >= 0; remove--) {
            if (staysConnected(n, edges, remove)) {
                return edges[remove];
            }
        }
        return new int[]{};
    }

    private boolean staysConnected(int n, int[][] edges, int skip) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int node = 0; node <= n; node++) {
            graph.add(new ArrayList<>());
        }
        for (int i = 0; i < edges.length; i++) {
            if (i == skip) {
                continue;
            }
            int a = edges[i][0];
            int b = edges[i][1];
            graph.get(a).add(b);
            graph.get(b).add(a);
        }

        boolean[] visited = new boolean[n + 1];
        Queue<Integer> queue = new ArrayDeque<>();
        queue.offer(1);
        visited[1] = true;
        int seen = 0;
        while (!queue.isEmpty()) {
            int node = queue.poll();
            seen++;
            for (int next : graph.get(node)) {
                if (!visited[next]) {
                    visited[next] = true;
                    queue.offer(next);
                }
            }
        }
        return seen == n;
    }
}
